function apiFetch(url, options={}){
  const headers={...(options.headers||{})}; if(currentWorkspaceId) headers['x-workspace-id']=currentWorkspaceId;
  return fetch(url,{...options,headers,credentials:'same-origin'});
}
function load(){ try { return JSON.parse(localStorage.getItem('flowpilot-state')) || structuredClone(seed) } catch { return structuredClone(seed) } }
function blankFlow(name,id=uid('flow')){return{id,name,live:false,zoom:1,selected:null,nodes:[{id:uid('n'),type:'trigger',name:'Novo gatilho',body:'Defina quando a automação começa',x:100,y:170,config:{triggerType:'keyword',keywords:['quero']}},{id:uid('n'),type:'message',name:'Primeira mensagem',body:'Escreva a mensagem enviada ao contato',x:390,y:170,config:{}}],edges:[]}}
function normalizeState(input){const s=input&&typeof input==='object'?input:structuredClone(seed);s.customFields=Array.isArray(s.customFields)?s.customFields:[];s.sequences=Array.isArray(s.sequences)?s.sequences:[];s.flows=Array.isArray(s.flows)&&s.flows.length?s.flows:(s.flow?[s.flow]:[]);s.automations=s.automations||[];for(const a of s.automations){let f=s.flows.find(x=>x.id===a.flowId)||s.flows.find(x=>x.name===a.name);if(!f){f=blankFlow(a.name);s.flows.push(f)}a.flowId=f.id}if(!s.sequences.some(x=>x.id==='seq_followup'))s.sequences.push({id:'seq_followup',name:'Follow-up padrão',status:'active',steps:[{id:'step_1',delayMs:0,text:'Olá, {{contact.name}}! Só passando para continuar nosso atendimento.'},{id:'step_2',delayMs:86400000,text:'Se ainda fizer sentido para você, posso te ajudar a avançar por aqui.'}]});if(!s.flow||!s.flows.some(x=>x.id===s.flow.id))s.flow=s.flows[0]||blankFlow('Nova automação');if(!s.flows.some(x=>x.id===s.flow.id))s.flows.push(s.flow);return s}
function syncCurrentFlow(){if(!state.flow)return;state.flows=state.flows||[];const i=state.flows.findIndex(x=>x.id===state.flow.id);if(i>=0)state.flows[i]=state.flow;else state.flows.push(state.flow)}
function save(){
  syncCurrentFlow();localStorage.setItem('flowpilot-state', JSON.stringify(state));
  if(sessionUser) apiFetch('/api/state',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(state)}).catch(()=>{});
}
async function hydrateFromServer(){
  try{
    const r=await apiFetch('/api/state',{cache:'no-store'});
    if(!r.ok)return;
    const remote=await r.json();
    if(remote && remote.workspace){ state=normalizeState(remote); try{const ir=await apiFetch('/api/integrations',{cache:'no-store'});if(ir.ok){const ij=await ir.json();integrationConnections=ij.connections||[];state.channels.forEach(ch=>{const c=integrationConnections.find(x=>x.provider===ch.id);ch.connected=!!c;ch.handle=c?.providerAccountId||''})}}catch{} localStorage.setItem('flowpilot-state',JSON.stringify(state)); render(); }
  }catch{}
}
async function reset(){
  try{
    const r=await apiFetch('/api/reset',{method:'POST'});
    if(r.ok){ state=await r.json(); localStorage.setItem('flowpilot-state',JSON.stringify(state)); render(); toast('Demo restaurada.'); return; }
  }catch{}
  state=structuredClone(seed); localStorage.setItem('flowpilot-state',JSON.stringify(state)); render(); toast('Demo restaurada.');
}
function esc(v=''){return String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function icon(n){ const map={home:'⌂',automations:'⌁',sequences:'⇢',contacts:'◎',inbox:'✉',broadcasts:'◢',analytics:'▥',settings:'⚙'}; return map[n]||'•' }
function setPage(p){state.activePage=p;save();render()}
function toast(msg){ const t=document.createElement('div');t.className='toast';t.textContent=msg;document.body.appendChild(t);setTimeout(()=>t.remove(),1800)}
function downloadJson(filename,data){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function modal({title,desc='',body,onSave,saveLabel='Salvar'}){
  const wrap=document.createElement('div');wrap.className='modal-backdrop';wrap.innerHTML=`<div class="modal"><h3>${esc(title)}</h3><p>${esc(desc)}</p><div class="modal-body">${body}</div><div class="modal-actions"><button class="btn cancel">Cancelar</button><button class="btn primary save">${esc(saveLabel)}</button></div></div>`;
  wrap.querySelector('.cancel').onclick=()=>wrap.remove();wrap.addEventListener('click',e=>{if(e.target===wrap)wrap.remove()});
  wrap.querySelector('.save').onclick=async()=>{wrap.querySelector('.save').disabled=true;try{const ok=await onSave?.(wrap);if(ok!==false)wrap.remove()}finally{if(wrap.isConnected)wrap.querySelector('.save').disabled=false}};document.body.appendChild(wrap);return wrap;
}

function shell(content,title,actions=''){
  const navs=[['home','Início'],['automations','Automações'],['sequences','Sequências'],['contacts','Contatos'],['inbox','Inbox'],['broadcasts','Disparos'],['analytics','Analytics'],['settings','Configurações']];
  const workspaceControl=!appConfig.personalMode&&sessionWorkspaces.length>1?`<select class="field workspace-select" id="workspaceSelect">${sessionWorkspaces.map(w=>`<option value="${esc(w.id)}" ${w.id===currentWorkspaceId?'selected':''}>${esc(w.name)}</option>`).join('')}</select>`:'';
  return `<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">FP</div>FlowPilot</div><div class="workspace-switch"><b>${esc(state.workspace.name)}</b><span>${appConfig.personalMode?'Uso pessoal':esc(state.workspace.plan)}</span></div><nav class="nav">${navs.map(([id,label])=>`<button class="nav-btn ${state.activePage===id?'active':''}" data-nav="${id}"><span class="nav-ico">${icon(id)}</span>${label}</button>`).join('')}</nav><div class="sidebar-bottom"><b>${esc(sessionUser?.name||'FlowPilot')}</b><br>${esc(sessionUser?.email||'')}<br><button class="link-btn" id="logoutBtn">Sair</button></div></aside><main class="main"><header class="topbar"><div class="page-title">${esc(title)}</div><div class="top-actions">${workspaceControl}${actions}${appConfig.personalMode?'':'<button class="btn small" id="resetDemo">Restaurar demo</button>'}</div></header>${content}</main></div>`;
}

function render(){
  let html='';
  if(state.activePage==='home') html=home();
  if(state.activePage==='automations') html=automations();
  if(state.activePage==='sequences') html=sequences();
  if(state.activePage==='contacts') html=contacts();
  if(state.activePage==='inbox') html=inbox();
  if(state.activePage==='broadcasts') html=broadcasts();
  if(state.activePage==='analytics') html=analytics();
  if(state.activePage==='settings') html=settings();
  if(state.activePage==='builder') html=builder();
  $('#app').innerHTML=html; bindGlobal(); bindPage();
}
function bindGlobal(){ $$('[data-nav]').forEach(b=>b.onclick=()=>setPage(b.dataset.nav)); const r=$('#resetDemo'); if(r) r.onclick=reset; const ws=$('#workspaceSelect'); if(ws) ws.onchange=async()=>{currentWorkspaceId=ws.value;localStorage.setItem('flowpilot-workspace',currentWorkspaceId);await hydrateFromServer()}; const lo=$('#logoutBtn'); if(lo) lo.onclick=logout; }
function bindPage(){
  const p=state.activePage;
  if(p==='home') bindHome(); if(p==='automations') bindAutomations(); if(p==='sequences') bindSequences(); if(p==='contacts') bindContacts(); if(p==='inbox') bindInbox(); if(p==='broadcasts') bindBroadcasts(); if(p==='analytics') bindAnalytics(); if(p==='settings') bindSettings(); if(p==='builder') bindBuilder();
}

function home(){
  const active=state.automations.filter(a=>a.status==='live').length;
  const totalRuns=state.automations.reduce((a,b)=>a+b.runs,0);
  const visibleChannels=appConfig.personalMode?state.channels.filter(c=>c.id==='instagram'):state.channels;
  const connected=visibleChannels.filter(c=>c.connected).length;
  const c=`<section class="content"><div class="grid cols-4"><div class="card metric"><div class="label">Contatos ativos</div><div class="value">${state.contacts.length}</div><div class="delta">+12% nos últimos 7 dias</div></div><div class="card metric"><div class="label">Automações ativas</div><div class="value">${active}</div><div class="delta">${totalRuns.toLocaleString('pt-BR')} execuções</div></div><div class="card metric"><div class="label">Conversas abertas</div><div class="value">${state.threads.length}</div><div class="delta">${state.threads.reduce((n,t)=>n+t.unread,0)} não lidas</div></div><div class="card metric"><div class="label">Canais conectados</div><div class="value">${connected}</div><div class="delta">de ${visibleChannels.length} ${appConfig.personalMode?'canal principal':'canais disponíveis'}</div></div></div>
  <div class="section-head"><div><h2>Automações recentes</h2><p>Monitore o que está rodando agora.</p></div><button class="btn primary" id="goAuto">Ver automações</button></div><div class="grid cols-2"><div class="card">${state.automations.slice(0,4).map(a=>`<div class="list-card"><div><div class="list-title">${esc(a.name)}</div><div class="list-meta">${esc(a.channel)} · ${a.runs} execuções</div></div><span class="pill ${a.status==='live'?'success':a.status==='paused'?'warning':''}">${a.status==='live'?'Ativa':a.status==='paused'?'Pausada':'Rascunho'}</span></div>`).join('')}</div><div class="card"><div class="builder-title">Canais</div><div class="builder-sub">Conexões do workspace e status dos provedores.</div>${visibleChannels.map(ch=>`<div class="channel-row"><div class="channel-info"><div class="channel-icon">${ch.icon}</div><div><div class="list-title">${esc(ch.name)}</div><div class="list-meta">${ch.connected?esc(ch.handle):'Não conectado'}</div></div></div><span class="pill ${ch.connected?'success':''}">${ch.connected?'Conectado':'Offline'}</span></div>`).join('')}</div></div></section>`;
  return shell(c,'Visão geral','<button class="btn primary" id="newFlowTop">+ Nova automação</button>');
}
function bindHome(){ $('#goAuto').onclick=()=>setPage('automations'); $('#newFlowTop').onclick=createAutomation; }

function automations(){
  const rows=state.automations.map(a=>`<tr><td><div class="list-title">${esc(a.name)}</div><div class="list-meta">Atualizada ${esc(a.updated)}</div></td><td>${esc(a.channel)}</td><td><span class="pill ${a.status==='live'?'success':a.status==='paused'?'warning':''}">${a.status==='live'?'Ativa':a.status==='paused'?'Pausada':'Rascunho'}</span></td><td>${a.runs}</td><td><div class="toolbar"><button class="btn small" data-edit-auto="${a.id}">Abrir</button><button class="btn small" data-dup-auto="${a.id}">Duplicar</button><button class="btn small danger" data-del-auto="${a.id}">Excluir</button></div></td></tr>`).join('');
  const c=`<section class="content"><div class="toolbar" style="justify-content:space-between;margin-bottom:14px"><input id="autoSearch" class="search" placeholder="Buscar automação"><div class="toolbar"><select id="autoFilter" class="field" style="width:150px"><option value="all">Todos os status</option><option value="live">Ativas</option><option value="draft">Rascunhos</option><option value="paused">Pausadas</option></select><button class="btn" id="templateGallery">Galeria de templates</button><button class="btn primary" id="newAutomation">+ Nova automação</button></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Automação</th><th>Canal</th><th>Status</th><th>Execuções</th><th>Ações</th></tr></thead><tbody id="autoRows">${rows}</tbody></table></div></section>`;
  return shell(c,'Automações');
}
function automationRows(){
  const q=($('#autoSearch')?.value||'').toLowerCase(); const f=$('#autoFilter')?.value||'all';
  $$('#autoRows tr').forEach(tr=>{const id=$('[data-edit-auto]',tr)?.dataset.editAuto;const a=state.automations.find(x=>x.id===id);tr.style.display=a&&a.name.toLowerCase().includes(q)&&(f==='all'||a.status===f)?'':'none'})
}
function bindAutomations(){
  $('#newAutomation').onclick=createAutomation; $('#templateGallery').onclick=openTemplateGallery; $('#autoSearch').oninput=automationRows; $('#autoFilter').onchange=automationRows;
  $$('[data-edit-auto]').forEach(b=>b.onclick=()=>openAutomation(b.dataset.editAuto));
  $$('[data-dup-auto]').forEach(b=>b.onclick=()=>{const a=state.automations.find(x=>x.id===b.dataset.dupAuto),source=state.flows.find(x=>x.id===a.flowId),flow=source?structuredClone(source):blankFlow(a.name);flow.id=uid('flow');flow.name=a.name+' — cópia';flow.live=false;state.flows.push(flow);state.automations.unshift({...a,id:uid('a'),flowId:flow.id,name:flow.name,status:'draft',runs:0,updated:'agora'});save();render();toast('Automação duplicada.')});
  $$('[data-del-auto]').forEach(b=>b.onclick=()=>{const a=state.automations.find(x=>x.id===b.dataset.delAuto);state.automations=state.automations.filter(x=>x.id!==b.dataset.delAuto);if(a?.flowId)state.flows=state.flows.filter(x=>x.id!==a.flowId);save();render();toast('Automação excluída.')});
}
function createAutomation(){
  modal({title:'Nova automação',desc:'Crie um fluxo independente e configure os blocos no construtor.',body:`<div class="form-group"><label>Nome</label><input class="field" id="mName" value="Nova automação"></div><div class="form-group"><label>Canal principal</label><select id="mChannel"><option>Instagram</option><option>WhatsApp</option><option>Messenger</option><option>Telegram</option></select></div>`,onSave:w=>{const name=$('#mName',w).value.trim();if(!name)return false;const flow=blankFlow(name),a={id:uid('a'),flowId:flow.id,name,status:'draft',channel:$('#mChannel',w).value,updated:'agora',runs:0};flow.edges=[{id:uid('e'),from:flow.nodes[0].id,to:flow.nodes[1].id}];state.flows.push(flow);state.automations.unshift(a);state.flow=flow;save();setPage('builder')}})
}
function openAutomation(id){syncCurrentFlow();const a=state.automations.find(x=>x.id===id);if(!a)return;let flow=state.flows.find(x=>x.id===a.flowId);if(!flow){flow=blankFlow(a.name);a.flowId=flow.id;state.flows.push(flow)}flow.live=a.status==='live';state.flow=flow;save();setPage('builder')}
async function openTemplateGallery(){
  const r=await apiFetch('/api/templates'),j=await r.json().catch(()=>({templates:[]}));if(!r.ok)return toast('Não foi possível carregar templates.');
  const w=modal({title:'Galeria de templates',desc:'Comece com um fluxo funcional e personalize no construtor.',body:`<div>${(j.templates||[]).map(t=>`<button class="list-card template-pick" style="width:100%;text-align:left" data-template="${esc(t.id)}"><div><div class="list-title">${esc(t.name)}</div><div class="list-meta">${esc(t.channel)} · ${esc(t.description)}</div></div><span>Usar →</span></button>`).join('')}</div>`,saveLabel:'Fechar',onSave:()=>true});
  $$('[data-template]',w).forEach(b=>b.onclick=()=>{
    const t=(j.templates||[]).find(x=>x.id===b.dataset.template);if(!t)return;
    const flow={...structuredClone(t.flow),id:uid('flow'),name:t.name,live:false,zoom:1,selected:null};
    flow.nodes=flow.nodes.map(n=>({...n,id:uid('n')}));const idMap=new Map(t.flow.nodes.map((n,i)=>[n.id,flow.nodes[i].id]));
    flow.edges=(t.flow.edges||[]).map(e=>({...e,id:uid('e'),from:idMap.get(e.from),to:idMap.get(e.to)}));
    const a={id:uid('a'),flowId:flow.id,name:t.name,status:'draft',channel:t.channel,updated:'agora',runs:0};state.flows.push(flow);state.automations.unshift(a);state.flow=flow;save();w.remove();setPage('builder');toast('Template aplicado.');
  });
}

function sequences(){
  const items=(state.sequences||[]).map(seq=>`<div class="card"><div style="display:flex;justify-content:space-between;gap:10px"><div><div class="list-title">${esc(seq.name)}</div><div class="list-meta">ID: ${esc(seq.id)} · ${(seq.steps||[]).length} etapa(s)</div></div><span class="pill ${seq.status==='active'?'success':'warning'}">${seq.status==='active'?'Ativa':'Pausada'}</span></div><div style="margin-top:12px">${(seq.steps||[]).map((st,i)=>`<div class="list-card"><div><div class="list-title">Etapa ${i+1}</div><div class="list-meta">espera ${formatDelay(st.delayMs)} · ${esc(st.text||st.template?.name||'mídia')}</div></div></div>`).join('')}</div><div class="toolbar" style="margin-top:12px"><button class="btn small" data-edit-seq="${seq.id}">Editar</button><button class="btn small danger" data-del-seq="${seq.id}">Excluir</button></div></div>`).join('');
  return shell(`<section class="content"><div class="section-head" style="margin-top:0"><div><h2>Sequências de follow-up</h2><p>Etapas persistentes executadas pela fila durável mesmo depois de horas ou dias.</p></div><button class="btn primary" id="newSequence">+ Nova sequência</button></div><div class="grid cols-2">${items||'<div class="empty"><b>Nenhuma sequência</b>Crie uma sequência e use uma ação enroll_sequence no construtor.</div>'}</div></section>`,'Sequências');
}
function formatDelay(ms){const n=Number(ms||0);if(!n)return'imediato';if(n%86400000===0)return`${n/86400000} dia(s)`;if(n%3600000===0)return`${n/3600000} hora(s)`;return`${Math.round(n/60000)} min`}
function sequenceModal(id=null){const seq=(state.sequences||[]).find(x=>x.id===id),lines=(seq?.steps||[]).map(s=>`${Math.round(Number(s.delayMs||0)/60000)} | ${s.text||''}`).join('\n');modal({title:id?'Editar sequência':'Nova sequência',desc:'Uma etapa por linha no formato: minutos de espera | mensagem. Variáveis como {{contact.name}} são suportadas.',body:`<div class="form-group"><label>Nome</label><input class="field" id="seqName" value="${esc(seq?.name||'Nova sequência')}"></div><div class="form-group"><label>ID técnico</label><input class="field" id="seqId" value="${esc(seq?.id||uid('seq'))}" ${id?'disabled':''}></div><div class="form-group"><label>Etapas</label><textarea id="seqSteps" rows="9" placeholder="0 | Olá, {{contact.name}}!\n1440 | Posso continuar te ajudando?">${esc(lines)}</textarea></div>`,onSave:async w=>{const name=$('#seqName',w).value.trim(),sequenceId=$('#seqId',w).value.trim(),steps=$('#seqSteps',w).value.split('\n').map((line,i)=>{const pos=line.indexOf('|');if(pos<0)return null;const mins=Number(line.slice(0,pos).trim()),text=line.slice(pos+1).trim();return text?{id:`step_${i+1}`,delayMs:Math.max(0,Number.isFinite(mins)?mins:0)*60000,text}:null}).filter(Boolean);if(!name||!sequenceId||!steps.length){toast('Informe nome, ID e pelo menos uma etapa válida.');return false}const r=await apiFetch('/api/sequences',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({id:sequenceId,name,status:seq?.status||'active',steps})}),j=await r.json().catch(()=>({}));if(!r.ok){toast(j.error||'Falha ao salvar sequência.');return false}await hydrateFromServer();toast('Sequência salva.');return true}})}
function bindSequences(){if($('#newSequence'))$('#newSequence').onclick=()=>sequenceModal();$$('[data-edit-seq]').forEach(b=>b.onclick=()=>sequenceModal(b.dataset.editSeq));$$('[data-del-seq]').forEach(b=>b.onclick=async()=>{if(!confirm('Excluir esta sequência?'))return;const r=await apiFetch(`/api/sequences/${encodeURIComponent(b.dataset.delSeq)}`,{method:'DELETE'});if(r.ok){await hydrateFromServer();toast('Sequência excluída.')}})}


function contacts(){
 const rows=state.contacts.map(c=>`<tr data-contact-row="${c.id}"><td><input type="checkbox" data-contact-select="${c.id}"></td><td><div class="contact-cell"><div class="avatar">${c.name.split(' ').map(x=>x[0]).slice(0,2).join('')}</div><div><div class="list-title">${esc(c.name)}</div><div class="list-meta">${esc(c.email)}</div></div></div></td><td>${esc(c.channel)}</td><td><span class="pill ${c.status==='Inscrito'?'success':'warning'}">${esc(c.status)}</span></td><td>${c.tags.map(t=>`<span class="pill purple" style="margin:2px">${esc(t)}</span>`).join('')}</td><td>${esc(c.last)}</td><td><button class="btn small" data-contact="${c.id}">Editar</button></td></tr>`).join('');
 const c=`<section class="content"><div class="toolbar" style="justify-content:space-between;margin-bottom:10px"><input class="search" id="contactSearch" placeholder="Buscar por nome, e-mail ou tag"><div class="toolbar"><button class="btn" id="bulkContacts">Ações em massa</button><button class="btn" id="importContacts">Importar CSV</button><button class="btn primary" id="newContact">+ Novo contato</button></div></div><div class="toolbar" style="margin-bottom:14px"><select class="field" id="contactChannel" style="width:160px"><option value="">Todos os canais</option><option>Instagram</option><option>WhatsApp</option></select><select class="field" id="contactStatus" style="width:160px"><option value="">Todos os status</option><option>Inscrito</option><option>Pausado</option><option>Descadastrado</option></select><input class="field" id="contactTag" placeholder="Filtrar por tag" style="max-width:220px"></div><div class="table-wrap"><table class="table"><thead><tr><th><input type="checkbox" id="selectAllContacts"></th><th>Contato</th><th>Canal</th><th>Status</th><th>Tags</th><th>Última interação</th><th></th></tr></thead><tbody id="contactRows">${rows}</tbody></table></div></section>`;
 return shell(c,'Contatos');
}
function applyContactFilters(){const q=($('#contactSearch')?.value||'').toLowerCase(),channel=$('#contactChannel')?.value||'',status=$('#contactStatus')?.value||'',tag=($('#contactTag')?.value||'').toLowerCase();$$('[data-contact-row]').forEach(tr=>{const c=state.contacts.find(x=>x.id===tr.dataset.contactRow),ok=c&&(!q||[c.name,c.email,c.phone,...(c.tags||[]),...Object.values(c.fields||{})].join(' ').toLowerCase().includes(q))&&(!channel||c.channel===channel)&&(!status||c.status===status)&&(!tag||(c.tags||[]).some(t=>String(t).toLowerCase().includes(tag)));tr.style.display=ok?'':'none'})}

