 $('#newContact').onclick=()=>editContact();$$('[data-contact]').forEach(b=>b.onclick=()=>editContact(b.dataset.contact));['#contactSearch','#contactChannel','#contactStatus','#contactTag'].forEach(sel=>{const el=$(sel);if(el)el.oninput=applyContactFilters});
