 const personalCard=appConfig.personalMode?`<div class="card"><div class="builder-title">Modo pessoal</div><div class="builder-sub">Esta instalação está travada em 1 administrador e 1 workspace. Cadastro público, múltiplos workspaces e cobrança estão desativados.</div><div class="toggle-row"><span>Administrador único</span><span class="pill success">Ativo</span></div><div class="toggle-row"><span>Workspace único</span><span class="pill success">Ativo</span></div><div class="toggle-row"><span>Billing/Stripe</span><span class="pill">Desativado</span></div></div>`:'';
